class MinStack:
    def __init__(self):
        self.stack = []
        self.min = None

    def push(self, val):
        if not self.stack:
            self.stack.append(val)
            self.min = val
        elif val < self.min:
            self.stack.append(2 * val - self.min)   # encoded: always < new min
            self.min = val
        else:
            self.stack.append(val)

    def pop(self):
        y = self.stack.pop()
        if y < self.min:               # encoded entry: the min is leaving
            self.min = 2 * self.min - y          # restore the previous min
        if not self.stack:
            self.min = None

    def top(self):
        y = self.stack[-1]
        return self.min if y < self.min else y

    def getMin(self):
        return self.min
